arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel&exclude_archived=true" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for c in d['channels']:
    if 'launch' in c['name'].lower():
        print(c['id'], c['name'], c.get('topic',''))
"

